  var groupIndex = 0;
  var groupSummary = document.getElementById('group-summary');

  function renderGroup(index){
    var g = GROUPS[index];
    var denomLine = '<div class="denom" data-stat="group-denominator">组内分母 4</div>';
    var head = '<div class="qhead"><div class="qtitle">' + esc(g.name) + '</div>' + denomLine + '</div>';
    return head + renderQuestions(g.summaries, false);
  }

  groupSummary.innerHTML = renderGroup(groupIndex);

  document.getElementById('next-group').addEventListener('click', function(){
    groupIndex = (groupIndex + 1) % GROUPS.length;
    groupSummary.innerHTML = renderGroup(groupIndex);
  });

  document.getElementById('comparison-standard-price').innerHTML = renderComparison(COMPARISONS[0]);
  document.getElementById('comparison-family-benefit').innerHTML = renderComparison(COMPARISONS[1]);
})();
</script>
</body>
